CREATE TABLE core_vertical (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE core_brand (id text PRIMARY KEY, vertical_id text NOT NULL REFERENCES core_vertical(id), name text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE core_tenant (id uuid PRIMARY KEY, brand_id text NOT NULL REFERENCES core_brand(id), name text NOT NULL, timezone text NOT NULL DEFAULT 'America/Sao_Paulo', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core_user (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES core_tenant(id), email text NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'admin' CHECK(role IN ('admin','staff')), UNIQUE(tenant_id,email), UNIQUE(tenant_id,id));
CREATE TABLE core_session (token_hash text PRIMARY KEY, tenant_id uuid NOT NULL, user_id uuid NOT NULL, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,user_id) REFERENCES core_user(tenant_id,id));
CREATE INDEX core_session_expiry ON core_session(expires_at);
CREATE TABLE core_customer (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES core_tenant(id), name text NOT NULL, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', UNIQUE(tenant_id,id));
CREATE TABLE core_resource (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES core_tenant(id), name text NOT NULL, days integer[] NOT NULL DEFAULT '{1,2,3,4,5,6}', opens text NOT NULL DEFAULT '08:00', closes text NOT NULL DEFAULT '18:00', UNIQUE(tenant_id,id));
CREATE TABLE core_service (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES core_tenant(id), name text NOT NULL, duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 5 AND 480), price_cents integer NOT NULL CHECK(price_cents>=0), UNIQUE(tenant_id,id));
CREATE TABLE core_booking (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES core_tenant(id), customer_id uuid NOT NULL, resource_id uuid NOT NULL, service_id uuid NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, price_cents integer NOT NULL CHECK(price_cents>=0), status text NOT NULL CHECK(status IN ('confirmed','completed','cancelled')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,customer_id) REFERENCES core_customer(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES core_resource(tenant_id,id), FOREIGN KEY(tenant_id,service_id) REFERENCES core_service(tenant_id,id));
CREATE INDEX core_booking_resource_period ON core_booking(tenant_id,resource_id,starts_at,ends_at) WHERE status <> 'cancelled';
CREATE TABLE core_time_block (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, resource_id uuid NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, reason text NOT NULL, CHECK(ends_at>starts_at), FOREIGN KEY(tenant_id,resource_id) REFERENCES core_resource(tenant_id,id));
CREATE TABLE core_audit (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES core_tenant(id), actor_id uuid NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,actor_id) REFERENCES core_user(tenant_id,id));
CREATE TABLE core_subscription (tenant_id uuid PRIMARY KEY REFERENCES core_tenant(id), status text NOT NULL CHECK(status IN ('trial','active','past_due','cancelled')), trial_ends_at timestamptz NOT NULL);
CREATE TABLE pet_pet (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_id uuid NOT NULL, name text NOT NULL, species text NOT NULL, breed text NOT NULL DEFAULT '', size text NOT NULL, notes text NOT NULL DEFAULT '', UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,customer_id) REFERENCES core_customer(tenant_id,id));
CREATE TABLE pet_booking (tenant_id uuid NOT NULL, booking_id uuid PRIMARY KEY, pet_id uuid NOT NULL, FOREIGN KEY(tenant_id,booking_id) REFERENCES core_booking(tenant_id,id), FOREIGN KEY(tenant_id,pet_id) REFERENCES pet_pet(tenant_id,id));
